<script setup>
import { ref, computed } from 'vue'
import references from './evidence/reference-components.json'
import source from './source-manifest.json'
import aliases from './icon-aliases.json'
import icons from './evidence/icons.json'
const single=ref('one'), multi=ref(['one']), date=ref('2025-12-18'), time=ref('2025-12-18T18:18:00'), required=ref(''), enabled=ref(true), checked=ref(true), radio=ref('a'), dialog=ref(null), notice=ref(''), dynamic=ref(false)
const options=computed(()=>[{value:'one',label:'选择器选项一'},{value:'two',label:'选择器选项二'},{value:'off',label:'禁用选项',disabled:true},...(dynamic.value?[{value:'three',label:'新增选项'}]:[])])
const events=ref([])
function record(name,event){events.value.unshift(`${name}: ${event?.target?.value ?? event}`);events.value=events.value.slice(0,8)}
const colors=['primary','primary-hover','primary-active','primary-disabled','accent','text','muted','disabled','bg','card','border','dropdown','table-head','selected','red','orange','green']
const buttonStates=['default','hover','active','disabled']
function submit(){notice.value='校验通过；仅修改此验收页中的数据。'}
</script>
<template>
  <main class="spec-showcase main admin-shell">
    <header><h1>UI 规范组件验收</h1><p>仅开发环境。源文件 SHA-256：<code>{{ source.sha256 }}</code></p><p>左侧为 Sketch 图层坐标、路径与样式导出，右侧为实际控件。图层预览不是 macOS Sketch 原生截图。</p></header>
    <section class="panel"><h2>基础颜色与字体</h2><div class="spec-colors"><div v-for="c in colors" :key="c"><span :style="{background:`var(--theme-${c})`}"></span><code>{{ c }}</code></div></div><p v-for="size in [24,18,16,14,12]" :key="size" :style="{fontSize:size+'px',lineHeight:(size+8)+'px'}">{{ size }}px · 思源黑体 / Arial 0123456789</p></section>
    <section class="panel"><h2>按钮 · 同一状态对照</h2><div v-for="(state,i) in buttonStates" :key="state" class="spec-compare"><div><code>{{ references[i].paintId }}</code><div v-html="references[i].svg"></div></div><div><code>{{ state }}</code><button class="button btn primary ui-state-button" :class="'spec-'+state" :disabled="state==='disabled'">按钮</button></div></div><div class="spec-row"><button class="button btn primary small">按钮</button><button class="button btn primary">普通按钮</button><button class="button btn primary large">登录操作</button><button class="button btn">次要按钮</button><button class="button btn" disabled>禁用</button><button class="button btn primary" aria-busy="true"><UiIcon name="loading" class="ui-spinning" />加载中</button></div></section>
    <section class="panel"><h2>输入、选择、日期与原生表单校验</h2><form class="spec-form" @submit.prevent="submit"><label>普通输入<input class="spec-input" aria-label="普通输入" placeholder="请输入内容" /></label><label>禁用输入<input class="spec-input" value="禁用内容" disabled /></label><label>错误输入<input class="spec-input" aria-invalid="true" value="错误状态" /></label><label>单选<UiSelect v-model="single" aria-label="单选" :options="options" @change="record('单选 change',$event)" /></label><label>多选<UiSelect v-model="multi" aria-label="多选" multiple :options="options" @change="record('多选 change',$event)" /></label><label>动态选项<UiSelect v-model="single" aria-label="动态选项"><option v-for="o in options" :key="o.value" :value="o.value" :disabled="o.disabled">{{ o.label }}</option></UiSelect></label><label>禁用选择<UiSelect model-value="one" :options="options" disabled /></label><label>必填选择<UiSelect v-model="required" aria-label="必填选择" required name="required"><option value="">请选择</option><option value="ok">有效选项</option></UiSelect></label><label>日期<UiDatePicker v-model="date" aria-label="日期" @change="record('日期 change',$event)" /></label><label>日期时间<UiDatePicker v-model="time" aria-label="日期时间" type="datetime-local" step="1" @change="record('日期时间 change',$event)" /></label><label>禁用日期<UiDatePicker model-value="2025-12-18" disabled /></label><label>日期范围限制<UiDatePicker model-value="2025-12-18" aria-label="日期范围限制" min="2025-12-10" max="2025-12-20" /></label><button type="button" class="button btn" @click="dynamic=!dynamic">切换动态选项</button><button type="submit" class="button btn primary">验证必填</button></form><output aria-label="模型值">{{ JSON.stringify({single,multi,date,time,required}) }}</output><p role="status">{{ notice }}</p><pre aria-label="事件记录">{{ events.join('\n') }}</pre></section>
    <section class="panel"><h2>原稿展开面板</h2><div class="spec-reference-grid"><figure v-for="r in references.slice(6,11)" :key="r.id"><figcaption>{{ r.path }}<br /><code>{{ r.paintId }}</code></figcaption><div v-html="r.svg"></div></figure></div></section>
    <section class="panel"><h2>选择状态、标签、页签、表格与提示</h2><div class="spec-row"><label><input v-model="checked" type="checkbox" />复选框</label><label><input type="checkbox" checked disabled />禁用选中</label><label><input v-model="radio" type="radio" value="a" />单选一</label><label><input v-model="radio" type="radio" value="b" />单选二</label><UiSwitch v-model="enabled" aria-label="开关" /><UiSwitch model-value disabled aria-label="禁用开关" /><button class="button btn" title="文字提示仅展示文本内容">查看文字提示</button></div><div class="spec-row"><span class="tag badge">默认标签</span><span class="tag badge green">完成</span><span class="tag badge red">异常</span><span class="tag badge orange">警告</span><button class="button btn" @click="dialog.showModal()">打开验收弹窗</button></div><div class="workspace-tabs tabs"><button class="active">当前页签</button><button>其他页签</button></div><table class="admin-table"><thead><tr><th>名称</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>示例行一</td><td><span class="badge tag">正常</span></td><td><button class="button btn">查看</button></td></tr><tr><td>示例行二</td><td>斑马纹</td><td><button class="button btn" disabled>禁用</button></td></tr></tbody></table><details class="spec-collapse"><summary>树与折叠面板</summary><label><input type="checkbox" />父级节点</label><div style="padding-left:24px"><label><input type="checkbox" />子级节点</label></div></details></section>
    <section class="panel"><h2>原稿图标与业务映射</h2><div class="spec-icons"><div v-for="(name,alias) in aliases" :key="alias"><UiIcon :name="alias" /><code>{{ alias }}</code><small>{{ name }} · {{ icons[name]?.id }}</small></div></div></section>
    <dialog ref="dialog" class="modal-panel spec-dialog"><header><h2>原生 dialog 中的展开控件</h2><button class="button btn" aria-label="关闭验收弹窗" @click="dialog.close()"><UiIcon name="close" /></button></header><div class="spec-form"><label>弹窗选择<UiSelect v-model="single" aria-label="弹窗选择" :options="options" /></label><label>弹窗日期<UiDatePicker v-model="time" aria-label="弹窗日期" type="datetime-local" step="1" /></label></div><footer><button class="button btn" @click="dialog.close()">取消</button></footer></dialog>
  </main>
</template>

